command:
$ErrorActionPreference = "Stop"
try {
  $response = Invoke-WebRequest -Uri "http://localhost:8000/index.html" -UseBasicParsing -TimeoutSec 5
  Write-Output "STATUS: $($response.StatusCode) | LENGTH: $($response.Content.Length)"
} catch {
  Write-Output "FAIL: $($_.Exception.Message)"
}

& curl.exe -s -o /dev/null -w "INDEX: %{http_code} | SIZE: %{size_download}
" http://localhost:8000/index.html; & curl.exe -s -o /dev/null -w "ARCHIVE: %{http_code} | SIZE: %{size_download}
" http://localhost:8000/archive.html; & curl.exe -s -o /dev/null -w "THREAD9988: %{http_code} | SIZE: %{size_download}
" http://localhost:8000/forum/thread-9988.html; & curl.exe -s -o /dev/null -w "STYLE: %{http_code} | SIZE: %{size_download}
" http://localhost:8000/assets/style.css

& "C:\Program Files\Python312\python.exe" -c "
import urllib.request
import re
for p in ['archive.html', 'contact.html', 'legal.html']:
    c = urllib.request.urlopen(f'http://localhost:8000/{p}').read().decode()
    # show all lines containing the words
    for line in c.split('\n'):
        if re.search(r'suspend|takedown', line, re.IGNORECASE):
            print(f'  {p}: {line.strip()[:130]}')
"

& "C:\Program Files\Python312\python.exe" -c "
import urllib.request
try:
    r = urllib.request.urlopen('https://api.github.com/repos/JVW-Hue/Mirror', timeout=5)
    import json
    d = json.loads(r.read())
    print('REPO EXISTS:', d.get('full_name'), '| default branch:', d.get('default_branch'), '| private:', d.get('private'))
except urllib.error.HTTPError as e:
    if e.code == 404:
        print('REPO 404 — JVW-Hue/Mirror does not exist on GitHub yet')
    else:
        print('HTTP', e.code)
except Exception as e:
    print('ERR:', e)
"
